func completenessLevelFromStats(stats json.RawMessage) string {
	if len(stats) == 0 {
		return ""
	}
	var s struct {
		CompletenessLevel string `json:"completeness_level"`
	}
	if err := json.Unmarshal(stats, &s); err != nil {
