	}
	return s.CompletenessLevel
}

// trustForCompleteness maps a provider completeness level to a coarse
// retrieval-trust label agents can branch on.
func trustForCompleteness(level string) string {
	switch level {
	case "ok":
		return "trusted"
	case "degraded":
		return "partial"
	case "unsafe":
		return "low"
	default:
		return "unknown"
	}
}

